package fr.perrier.guard.utils;

/**
 * Textures MineSkin (value + signature) codées en dur, une par icône de menu custom.
 * Généré depuis tools/headgen/textures.txt — zéro réseau à l'exécution.
 * Si l'API Bukkit profile est absente, Heads.textured() retombe sur l'item vanilla.
 */
public enum GuardHeads {
    PROFILE_SANCTIONS("profile_sanctions","",""),
    PROFILE_INVENTORY("profile_inventory","",""),
    PROFILE_HISTORY("profile_history","",""),
    MODERATION_VANISH("moderation_vanish","",""),
    MODERATION_CHATLOCK("moderation_chatlock","",""),
    MODERATION_STAFFCHAT("moderation_staffchat","",""),
    MODERATION_NOCLIP("moderation_noclip","","");

    private final String key;
    private final String value;
    private final String signature;

    GuardHeads(String key, String value, String signature) {
        this.key = key;
        this.value = value;
        this.signature = signature;
    }

    /** {value, signature} pour une clé d'icône, ou null si la clé est inconnue. */
    public static String[] texture(String key) {
        for (GuardHeads head : values()) {
            if (head.key.equals(key)) {
                return new String[] {head.value, head.signature};
            }
        }
        return null;
    }
}
